-- Complete TPC-H Database - Fresh Install
-- Drops all existing tables and recreates everything
-- 5 tables with ~1,380 total rows

USE tpch;

-- Drop tables in reverse order (foreign keys)
SET FOREIGN_KEY_CHECKS=0;
DROP TABLE IF EXISTS LINEITEM;
DROP TABLE IF EXISTS ORDERS;
DROP TABLE IF EXISTS CUSTOMER;
DROP TABLE IF EXISTS NATION;
DROP TABLE IF EXISTS REGION;
SET FOREIGN_KEY_CHECKS=1;

-- ======================
-- TABLE 1: REGION (5 rows)
-- ======================
CREATE TABLE REGION (
    R_REGIONKEY INT NOT NULL PRIMARY KEY,
    R_NAME      CHAR(25) NOT NULL,
    R_COMMENT   VARCHAR(152)
) ENGINE=InnoDB;


-- ======================
-- TABLE 2: NATION (25 rows)
-- ======================
CREATE TABLE NATION (
    N_NATIONKEY INT NOT NULL PRIMARY KEY,
    N_NAME      CHAR(25) NOT NULL,
    N_REGIONKEY INT NOT NULL,
    N_COMMENT   VARCHAR(152),
    FOREIGN KEY (N_REGIONKEY) REFERENCES REGION(R_REGIONKEY),
    INDEX idx_nation_region (N_REGIONKEY)
) ENGINE=InnoDB;


-- ======================
-- TABLE 3: CUSTOMER (150 rows)
-- ======================
CREATE TABLE CUSTOMER (
    C_CUSTKEY    INT NOT NULL PRIMARY KEY,
    C_NAME       VARCHAR(25) NOT NULL,
    C_ADDRESS    VARCHAR(40) NOT NULL,
    C_NATIONKEY  INT NOT NULL,
    C_PHONE      CHAR(15) NOT NULL,
    C_ACCTBAL    DECIMAL(15,2) NOT NULL,
    C_MKTSEGMENT CHAR(10),
    C_COMMENT    VARCHAR(117),
    FOREIGN KEY (C_NATIONKEY) REFERENCES NATION(N_NATIONKEY),
    INDEX idx_customer_nation (C_NATIONKEY)
) ENGINE=InnoDB;


-- ======================
-- TABLE 4: ORDERS (300 rows)
-- ======================
CREATE TABLE ORDERS (
    O_ORDERKEY      INT NOT NULL PRIMARY KEY,
    O_CUSTKEY       INT NOT NULL,
    O_ORDERSTATUS   CHAR(1) NOT NULL,
    O_TOTALPRICE    DECIMAL(15,2) NOT NULL,
    O_ORDERDATE     DATE NOT NULL,
    O_ORDERPRIORITY CHAR(15) NOT NULL,
    O_CLERK         CHAR(15) NOT NULL,
    O_SHIPPRIORITY  INT NOT NULL,
    O_COMMENT       VARCHAR(79),
    FOREIGN KEY (O_CUSTKEY) REFERENCES CUSTOMER(C_CUSTKEY),
    INDEX idx_orders_customer (O_CUSTKEY),
    INDEX idx_orders_date (O_ORDERDATE)
) ENGINE=InnoDB;


-- ======================
-- TABLE 5: LINEITEM (900+ rows)
-- ======================
CREATE TABLE LINEITEM (
    L_ORDERKEY      INT NOT NULL,
    L_PARTKEY       INT NOT NULL,
    L_SUPPKEY       INT NOT NULL,
    L_LINENUMBER    INT NOT NULL,
    L_QUANTITY      DECIMAL(15,2) NOT NULL,
    L_EXTENDEDPRICE DECIMAL(15,2) NOT NULL,
    L_DISCOUNT      DECIMAL(15,2) NOT NULL,
    L_TAX           DECIMAL(15,2) NOT NULL,
    L_RETURNFLAG    CHAR(1) NOT NULL,
    L_LINESTATUS    CHAR(1) NOT NULL,
    L_SHIPDATE      DATE NOT NULL,
    L_COMMITDATE    DATE NOT NULL,
    L_RECEIPTDATE   DATE NOT NULL,
    L_SHIPINSTRUCT  CHAR(25) NOT NULL,
    L_SHIPMODE      CHAR(10) NOT NULL,
    L_COMMENT       VARCHAR(44),
    PRIMARY KEY (L_ORDERKEY, L_LINENUMBER),
    FOREIGN KEY (L_ORDERKEY) REFERENCES ORDERS(O_ORDERKEY),
    INDEX idx_lineitem_order (L_ORDERKEY),
    INDEX idx_lineitem_shipdate (L_SHIPDATE)
) ENGINE=InnoDB;


-- Verification queries
SELECT 'REGION' as table_name, COUNT(*) as row_count FROM REGION
UNION ALL SELECT 'NATION', COUNT(*) FROM NATION
UNION ALL SELECT 'CUSTOMER', COUNT(*) FROM CUSTOMER
UNION ALL SELECT 'ORDERS', COUNT(*) FROM ORDERS
UNION ALL SELECT 'LINEITEM', COUNT(*) FROM LINEITEM;

